<script setup>
import { onMounted, onBeforeUnmount, ref, watch, nextTick } from 'vue'
import * as echarts from 'echarts'
import { useAppStore } from '../stores/app'
const app = useAppStore()
const props = defineProps({ metrics: { type: Object, default: () => ({ training: [], evaluation: [] }) } })
const els = ref([]), charts = []
const specs = [ ['累计奖励 / 综合得分',['episode_reward','objective_score']], ['任务完成率 / 超时率',['task_success_rate','deadline_miss_rate']], ['平均完成时延 (s)',['avg_delay_s']], ['平均任务能耗 (J)',['avg_energy_j']], ['负载均衡度 / 方差',['load_balance_degree','mean_load_variance']], ['平均跳数 / PPO 诊断',['mean_hops_accepted','approx_kl','entropy','loss']], ['DAG Makespan (s)',['avg_dag_makespan_s']], ['分芯片负载标准差',['cpu_load_std','npu_load_std','fpga_load_std']], ['FPGA 重构率',['fpga_reconfig_rate']] ]
function render() { specs.forEach((spec,i) => { if (!charts[i] && els.value[i]) { charts[i] = echarts.init(els.value[i]); charts[i].on('legendselectchanged', event => { app.prefs.chartLegend = { ...app.prefs.chartLegend, [i]: event.selected } }) } if (!charts[i]) return; const series = []; for (const [group, data] of Object.entries(props.metrics || {})) { if (!Array.isArray(data)) continue; for (const key of spec[1]) { const values = data.map((r,idx) => [r.episode ?? idx+1, r[key] ?? r[key+'_mean']]).filter(p=>p[1] != null); if (values.length) series.push({name:`${group === 'training' ? '训练' : '验证'} · ${key}`,type:'line',showSymbol:false,smooth:false,data:values}) } } charts[i].setOption({ color:['#247eae','#44aa98','#e5a34d','#d86b68','#8c85bd','#789aaa'], tooltip:{trigger:'axis'}, legend:{type:'scroll',bottom:0,selected:app.prefs.chartLegend?.[i] || {},textStyle:{fontSize:10,color:'#aec9e4'}}, grid:{top:15,right:16,bottom:48,left:55}, xAxis:{axisLabel:{color:'#aec9e4'},type:'value',name:'回合',nameTextStyle:{fontSize:10},splitLine:{show:false}}, yAxis:{axisLabel:{color:'#aec9e4'},type:'value',scale:true,splitLine:{lineStyle:{color:'#194363'}}}, series },true) }) }
function resize(){ charts.forEach(c=>c?.resize()) }
onMounted(() => { render(); window.addEventListener('resize',resize) }); onBeforeUnmount(()=>{ window.removeEventListener('resize',resize); charts.forEach(c=>c?.dispose()) }); watch(()=>props.metrics,()=>nextTick(render),{deep:true})
</script>
<template><div class="chart-grid"><div v-for="(s,i) in specs.filter((s, i) => i < 6 || Object.values(metrics).some(rows => Array.isArray(rows) && rows.some(row => s[1].some(key => row[key] != null || row[key + '_mean'] != null))))" :key="s[0]" class="chart-card"><h4>{{ s[0] }}</h4><div :ref="el => els[i]=el" class="chart"></div></div></div></template>
